#pragma once
namespace spark {
inline constexpr const char* command_explorer_html=R"HTML(<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SPARK · Commands</title>
<style>body{margin:0;background:#101820;color:#e5edf3;font:16px system-ui}main{max-width:1100px;margin:auto;padding:28px 20px}a{color:#78dfcc}header,.row{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}section,article{background:#1a2935;border:1px solid #324957;border-radius:10px;padding:20px;margin:16px 0}button,input,textarea{font:inherit;padding:10px;border-radius:6px;border:1px solid #56717f}button{background:#78dfcc;color:#102029;cursor:pointer}button:disabled{opacity:.5;cursor:wait}p,small{color:#adc1ce}.action{padding:10px 0;border-top:1px solid #324957}code{overflow-wrap:anywhere}dialog{max-width:600px;width:85%;background:#1a2935;color:white;border:1px solid #56717f;border-radius:12px}dialog::backdrop{background:#0009}label{display:block;margin:16px 0 6px}textarea,input{box-sizing:border-box;width:100%;background:#101820;color:white}textarea{height:180px;font-family:monospace}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto}.error{color:#ffb5ad}.buttons{display:flex;gap:12px;margin-top:20px}h2{overflow-wrap:anywhere}[role=status]{min-height:24px}</style>
<main><header><div><a href="/">← Dashboard</a><h1>Command explorer</h1></div><button id="refresh">Refresh devices</button></header>
<p>Choose an action to run once on its device. Devices execute queued commands when connected.</p><div id="notice" role="status"></div><div id="devices"></div>
<section><h2>Runs from this page</h2><p>Results update automatically. Keep this page open to follow execution.</p><div id="runs"><p id="empty">No commands submitted yet.</p></div></section></main>
<dialog id="dialog"><form id="form"><h2 id="title"></h2><p id="target"></p><label for="input">Input parameters (JSON object)</label><textarea id="input" spellcheck="false">{}</textarea><label for="expiry">Queue expiry (seconds)</label><input id="expiry" type="number" min="1" max="604800" value="300" required><div id="form-error" class="error" role="alert"></div><div class="buttons"><button id="submit" type="submit">Run once</button><button type="button" id="cancel">Cancel</button></div></form></dialog>
<script src="/auth/client.js"></script>
<script>
const $=id=>document.getElementById(id);let selected=null,source=null,registering=null,loading=false,polling=false;const jobs=[];
function randomId(){const a=new Uint8Array(16);crypto.getRandomValues(a);return Array.from(a,x=>x.toString(16).padStart(2,'0')).join('');}
async function api(path,method='GET',body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch(path,{method,signal:controller.signal,headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error||('HTTP '+r.status));return data;}finally{clearTimeout(timer);}}
async function requester(){const session=await sparkSession.ready;if(session.mode==='session')return undefined;if(registering)return registering;registering=(async()=>{if(!source){try{source=localStorage.getItem('spark-command-explorer-device');}catch(e){}if(!/^explorer-[0-9a-f]{32}$/.test(source||'')){source='explorer-'+randomId();try{localStorage.setItem('spark-command-explorer-device',source);}catch(e){}}}try{await api('/devices/'+source,'POST',{local_ip:'0.0.0.0'});}catch(e){if(e.message!=='device_exists')throw e;}return source;})();try{return await registering;}finally{registering=null;}}
function openRun(device,action){selected={device,action};$('title').textContent=action;$('target').textContent='Target device: '+device;$('input').value='{}';$('expiry').value='300';$('form-error').textContent='';$('dialog').showModal();}
async function devices(){if(loading)return;loading=true;$('refresh').disabled=true;$('notice').textContent='Loading devices…';try{const fragment=document.createDocumentFragment();let offset=0,total=0;for(;;){const page=await api('/commands/devices?limit=100&offset='+offset);for(const d of page.devices){total++;const card=document.createElement('article'),heading=document.createElement('h2'),address=document.createElement('p');heading.textContent=d.id;address.textContent=d.local_ip;card.append(heading,address);for(const action of d.actions){const row=document.createElement('div'),name=document.createElement('code'),button=document.createElement('button');row.className='row action';name.textContent=action;button.textContent='Run once';button.dataset.sparkPermission='commands.invoke';button.onclick=()=>openRun(d.id,action);row.append(name,button);card.append(row);}fragment.append(card);}if(page.devices.length<100)break;offset+=100;}$('devices').replaceChildren(fragment);$('notice').textContent=total?total+' device(s) exposing actions.':'No devices advertise actions yet.';}catch(e){$('notice').textContent='Cannot load devices: '+e.message;}finally{loading=false;$('refresh').disabled=false;}}
function render(job,record){job.record=record;job.status.textContent=record.status+' · '+record.id;job.output.textContent=JSON.stringify({executing_device:record.executing_device,result:record.result,error:record.error},null,2);job.link.href='/commands/'+encodeURIComponent(record.id);job.link.hidden=false;job.retry.hidden=true;}
async function submit(job){if(job.sending)return;job.sending=true;job.retry.disabled=true;job.status.textContent='Submitting…';try{render(job,await api('/commands','POST',job.packet));}catch(e){job.status.textContent='Submission not confirmed: '+e.message+'. Retry uses the same request key.';job.retry.hidden=false;}finally{job.sending=false;job.retry.disabled=false;}}
$('form').onsubmit=async e=>{e.preventDefault();if($('submit').disabled)return;let input;try{input=JSON.parse($('input').value);if(!input||Array.isArray(input)||typeof input!=='object')throw Error('Enter a JSON object.');}catch(e){$('form-error').textContent=e.message;return;}const expiry=Number($('expiry').value);if(!Number.isInteger(expiry)||expiry<1||expiry>604800){$('form-error').textContent='Queue expiry must be 1–604800 seconds.';return;}const choice={...selected};$('submit').disabled=true;$('cancel').disabled=true;try{const packet={source_device:await requester(),target_device:choice.device,action:choice.action,input,expires_in_seconds:expiry,idempotency_key:'explorer-'+randomId()};if(new TextEncoder().encode(JSON.stringify(packet)).length>16384)throw Error('Request exceeds the 16 KiB limit.');const card=document.createElement('article'),heading=document.createElement('h3'),status=document.createElement('p'),output=document.createElement('pre'),retry=document.createElement('button'),link=document.createElement('a');heading.textContent=packet.action+' → '+packet.target_device;retry.textContent='Retry submission';retry.hidden=true;link.textContent='View command JSON';link.hidden=true;card.append(heading,status,output,link,retry);$('empty')?.remove();$('runs').prepend(card);const job={packet,status,output,retry,link,record:null,sending:false};jobs.push(job);retry.onclick=()=>submit(job);$('dialog').close();await submit(job);}catch(e){$('form-error').textContent=e.message;}finally{$('submit').disabled=false;$('cancel').disabled=false;}};
async function poll(){if(polling)return;polling=true;try{for(const job of jobs){if(!job.record||!['queued','running'].includes(job.record.status))continue;try{render(job,await api('/commands/'+encodeURIComponent(job.record.id)));}catch(e){job.status.textContent='Waiting for server: '+e.message;}}}finally{polling=false;}}
$('dialog').addEventListener('cancel',e=>{if($('submit').disabled)e.preventDefault();});$('cancel').onclick=()=>$('dialog').close();$('refresh').onclick=devices;devices();setInterval(poll,2000);
</script></html>)HTML";
}
